export function getConstitutionTitle(
  section: ConstitutionSection,
  lang: Lang,
): string {
  return section.titles[lang] ?? section.titles.en;
}

export function getConstitutionBlocks(
  section: ConstitutionSection,
  lang: Lang,
): string[] {
  const blocks = section.blocks[lang];
  if (blocks?.length) return blocks;
  return section.blocks.en;
}
